tool.command:

  ln -f -s ${input_topology_filepath} ${input_topology_filepath}_`echo $$`.${input_topology_filepath.ext};

  ln -f -s ${input_structure_filepath} ${input_structure_filepath}_`echo $$`.${input_structure_filepath.ext};

  ln -f -s ${input_trajectory_filepath} ${input_trajectory_filepath}_`echo $$`.${input_trajectory_filepath.ext};

  ln -f -s ${input_inputs_filepath} ${input_inputs_filepath}_`echo $$`.${input_inputs_filepath.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

distance_per_residue

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__interactions__dq__:${properties.interactions},__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_topology_filepath) != 'None':
    --input_topology_filepath ${input_topology_filepath}_`echo $$`.${input_topology_filepath.ext}
  #end if

  #if str($input_structure_filepath) != 'None':
    --input_structure_filepath ${input_structure_filepath}_`echo $$`.${input_structure_filepath.ext}
  #end if

  #if str($input_trajectory_filepath) != 'None':
    --input_trajectory_filepath ${input_trajectory_filepath}_`echo $$`.${input_trajectory_filepath.ext}
  #end if

  #if str($input_inputs_filepath) != 'None':
    --input_inputs_filepath ${input_inputs_filepath}_`echo $$`.${input_inputs_filepath.ext}
  #end if


  --output_analysis_zip_path $outname_output_analysis_zip_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_topology_filepath}_`echo $$`.${input_topology_filepath.ext};

  rm -f ${input_structure_filepath}_`echo $$`.${input_structure_filepath.ext};

  rm -f ${input_trajectory_filepath}_`echo $$`.${input_trajectory_filepath.ext};

  rm -f ${input_inputs_filepath}_`echo $$`.${input_inputs_filepath.ext};


  if test -f $outname_output_analysis_zip_path; then mv $outname_output_analysis_zip_path $output_analysis_zip_path; fi;
